// 从 topic 取设备名，例如 zigbee2mqtt/0x00158d0001 → 0x00158d0001
var device = msg.topic.split('/').pop();

// 读取全局缓存（跨消息持久）
var cache = global.get('zigbee_cache') || {};

// 只缓存数值和布尔类型字段
var fields = {};
Object.keys(msg.payload).forEach(function(k) {
    var v = msg.payload[k];
    if (typeof v === 'number' || typeof v === 'boolean') {
        fields[k] = v;
    }
});

if (Object.keys(fields).length > 0) {
    cache[device] = fields;
    global.set('zigbee_cache', cache);
    node.log('已缓存设备: ' + device + ' 字段数: ' + Object.keys(fields).length);
}

return null; // 不向下传递，等定时触发

var cache = global.get('zigbee_cache') || {};

if (Object.keys(cache).length === 0) {
    node.warn('缓存为空，跳过本次推送');
    return null;
}

var lines = [];

Object.keys(cache).forEach(function(device) {
    var fields = cache[device];
    Object.keys(fields).forEach(function(key) {
        var value = fields[key];
        var numeric = (typeof value === 'boolean') ? (value ? 1 : 0) : value;
        var metricName = 'zigbee_' + key.replace(/[^a-zA-Z0-9_]/g, '_');
        var label = 'device="' + device + '"';
        lines.push('# TYPE ' + metricName + ' gauge');
        lines.push(metricName + '{' + label + '} ' + numeric);
    });
});

msg.payload = lines.join('\n') + '\n';
msg.headers = { 'Content-Type': 'text/plain; version=0.0.4' };

node.log('推送 ' + Object.keys(cache).length + ' 个设备到 Pushgateway');
return msg;
